// Valida la entrada y separa paradas con coordenadas de las que hay que geocodificar.
// Nunca lanza errores: si algo está mal devuelve valido=false para que se responda.
const cfg = $('Config').first().json;
const body = $('Webhook').first().json.body;

const enRango = (lat, lon) =>
  Number.isFinite(lat) && Number.isFinite(lon) &&
  lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180;
const aNumero = (v) => (v === null || v === undefined || v === '' ? NaN : Number(v));
const invalido = (status, error, detalle) =>
  [{ json: { valido: false, status, error, detalle } }];

const depotLat = aNumero(cfg.DEPOT_LAT);
const depotLon = aNumero(cfg.DEPOT_LON);
if (!enRango(depotLat, depotLon) || (depotLat === 0 && depotLon === 0)) {
  return invalido(500, 'configuracion_incompleta', 'Definir DEPOT_LAT y DEPOT_LON (variables de entorno de n8n)');
}
// La API key de ORS se lee del entorno en los nodos HTTP; aquí solo se
// verifica que exista (nunca se copia a los datos de la ejecución).
let orsKey = '';
try {
  orsKey = String($env.OPENROUTESERVICE_API_KEY || '').trim();
} catch (e) {
  orsKey = '';
}
if (!orsKey) {
  return invalido(500, 'configuracion_incompleta', 'Definir OPENROUTESERVICE_API_KEY (variable de entorno de n8n)');
}

if (!body || !Array.isArray(body.paradas)) {
  return invalido(400, 'entrada_invalida', 'Se esperaba {"paradas": [...]}');
}

const resueltas = [];
const pendientes = [];
const sin_resolver = [];
const ids_recibidos = [];
const vistos = new Set();

for (const p of body.paradas) {
  let id = p ? p.pedido_id : undefined;
  if (typeof id === 'string' && /^\d+$/.test(id)) id = Number(id);
  if (!Number.isInteger(id)) {
    return invalido(400, 'entrada_invalida', 'pedido_id debe ser entero: ' + JSON.stringify(p));
  }
  // Un pedido_id repetido se considera una sola parada (la primera).
  if (vistos.has(id)) continue;
  vistos.add(id);
  ids_recibidos.push(id);

  const lat = aNumero(p.latitud);
  const lon = aNumero(p.longitud);
  const direccion = typeof p.direccion_texto === 'string' ? p.direccion_texto.trim() : '';

  if (enRango(lat, lon)) {
    resueltas.push({ pedido_id: id, latitud: lat, longitud: lon });
  } else if (direccion) {
    pendientes.push({ pedido_id: id, direccion_texto: direccion });
  } else {
    sin_resolver.push({ pedido_id: id, motivo: 'dirección no encontrada' });
  }
}

return [{ json: { valido: true, ids_recibidos, resueltas, pendientes, sin_resolver } }];

// Junta el resultado de la geocodificación con las paradas que ya tenían coordenadas.
const cfg = $('Config').first().json;
const base = $('Normalizar').first().json;
const pendientes = $('Separar pendientes').all().map((i) => i.json);
const respuestas = $input.all();
const minConfianza = Number(cfg.CONFIDENCE_MIN);

const resueltas = [...base.resueltas];
const sin_resolver = [...base.sin_resolver];

pendientes.forEach((p, i) => {
  const r = respuestas[i] ? respuestas[i].json : null;
  if (!r || r.error || !Array.isArray(r.features)) {
    sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'error de geocodificación' });
    return;
  }
  const f = r.features[0];
  const coords = f && f.geometry && f.geometry.coordinates;
  if (!f || !Array.isArray(coords) || coords.length < 2) {
    sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'dirección no encontrada' });
    return;
  }
  const props = f.properties || {};
  // El confidence de ORS no basta: una dirección inventada puede volver con confidence 1 y
  // match_type "exact" apuntando al centroide de otra calle. Solo se acepta un punto exacto.
  if (props.layer !== 'address') {
    sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'dirección no encontrada con precisión suficiente' });
    return;
  }
  const confianza = Number(props.confidence);
  if (!(confianza >= minConfianza)) {
    sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'dirección ambigua' });
    return;
  }
  // ORS devuelve [lon, lat].
  const lon = Number(coords[0]);
  const lat = Number(coords[1]);
  if (!(lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180)) {
    sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'error de geocodificación' });
    return;
  }
  resueltas.push({ pedido_id: p.pedido_id, latitud: lat, longitud: lon });
});

return [{ json: { ids_recibidos: base.ids_recibidos, resueltas, sin_resolver } }];

// Llega desde Normalizar (sin geocodificar) o desde Evaluar geocodificación; ambos con la misma forma.
const cfg = $('Config').first().json;
const d = $input.first().json;
const depot = [Number(cfg.DEPOT_LON), Number(cfg.DEPOT_LAT)];

const body_optimizacion = {
  vehicles: [{ id: 1, profile: 'driving-car', start: depot, end: depot }],
  jobs: d.resueltas.map((p) => ({ id: p.pedido_id, location: [p.longitud, p.latitud] })),
};

return [{
  json: {
    ids_recibidos: d.ids_recibidos,
    resueltas: d.resueltas,
    sin_resolver: d.sin_resolver,
    body_optimizacion,
  },
}];

// Arma {ruta, sin_resolver} y verifica el contrato antes de responder.
// Si algo no cuadra, valido=false y se responde 502 (nunca una ruta parcial).
const prep = $('Preparar optimización').first().json;
const opt = $input.first().json;

const porId = new Map(prep.resueltas.map((p) => [p.pedido_id, p]));
const ruta = [];
const sin_resolver = [...prep.sin_resolver];
const errores = [];

if (prep.resueltas.length > 0) {
  if (!opt || !Array.isArray(opt.routes) || (opt.code !== undefined && opt.code !== 0)) {
    errores.push('respuesta de optimización inesperada');
  } else {
    const steps = opt.routes[0] && Array.isArray(opt.routes[0].steps) ? opt.routes[0].steps : [];
    const enRuta = new Set();
    for (const s of steps) {
      if (s.type !== 'job') continue;
      const p = porId.get(s.id);
      if (!p || enRuta.has(s.id)) {
        errores.push('job desconocido o repetido: ' + s.id);
        continue;
      }
      enRuta.add(s.id);
      // Se devuelven las coordenadas propias (las recibidas o las geocodificadas).
      ruta.push({ pedido_id: p.pedido_id, orden_entrega: ruta.length + 1, latitud: p.latitud, longitud: p.longitud });
    }
    // Lo que no quedó en la ruta (unassigned u omitido) va a sin_resolver.
    for (const p of prep.resueltas) {
      if (!enRuta.has(p.pedido_id)) {
        sin_resolver.push({ pedido_id: p.pedido_id, motivo: 'no asignable en la optimización' });
      }
    }
  }
}

// Verificación del contrato.
const apariciones = new Map();
for (const x of [...ruta, ...sin_resolver]) {
  apariciones.set(x.pedido_id, (apariciones.get(x.pedido_id) || 0) + 1);
}
for (const id of prep.ids_recibidos) {
  if (apariciones.get(id) !== 1) errores.push('pedido_id ' + id + ' aparece ' + (apariciones.get(id) || 0) + ' veces');
}
for (const id of apariciones.keys()) {
  if (!prep.ids_recibidos.includes(id)) errores.push('pedido_id no recibido: ' + id);
}
ruta.forEach((r, i) => {
  if (r.orden_entrega !== i + 1) errores.push('orden_entrega inválido en ' + r.pedido_id);
  if (!(r.latitud >= -90 && r.latitud <= 90 && r.longitud >= -180 && r.longitud <= 180)) {
    errores.push('coordenadas fuera de rango en ' + r.pedido_id);
  }
});

return [{ json: { valido: errores.length === 0, errores, respuesta: { ruta, sin_resolver } } }];
